def ledger(ops: list[str]) -> tuple[dict[str, int], list[int]]:
    bal: dict[str, int] = {}
    frozen: dict[str, bool] = {}
    stack: list[tuple] = []
    rejected: list[int] = []

    def valid_amount(s: str) -> bool:
        return s != "" and all("0" <= c <= "9" for c in s)

    for i, op in enumerate(ops):
        t = op.split(" ")
        verb, count = t[0], len(t)
        success = False

        if verb == "undo":
            if count == 1 and stack:
                rec = stack.pop()
                kind = rec[0]
                if kind == "open":
                    name = rec[1]
                    del bal[name]
                    del frozen[name]
                elif kind == "add":
                    bal[rec[1]] += rec[2]
                elif kind == "transfer":
                    _, a, b, n = rec
                    bal[a] += n
                    bal[b] -= n
                elif kind == "frz":
                    frozen[rec[1]] = rec[2]
                success = True

        elif verb == "open" and count == 3 and valid_amount(t[2]):
            a, n = t[1], int(t[2])
            if a not in bal:
                bal[a] = n
                frozen[a] = False
                stack.append(("open", a))
                success = True

        elif verb == "deposit" and count == 3 and valid_amount(t[2]):
            a, n = t[1], int(t[2])
            if n > 0 and a in bal:
                bal[a] += n
                stack.append(("add", a, -n))
                success = True

        elif verb == "withdraw" and count == 3 and valid_amount(t[2]):
            a, n = t[1], int(t[2])
            if n > 0 and a in bal and not frozen[a] and bal[a] >= n:
                bal[a] -= n
                stack.append(("add", a, n))
                success = True

        elif verb == "transfer" and count == 4 and valid_amount(t[3]):
            a, b, n = t[1], t[2], int(t[3])
            if (n > 0 and a != b and a in bal and b in bal
                    and not frozen[a] and bal[a] >= n):
                bal[a] -= n
                bal[b] += n
                stack.append(("transfer", a, b, n))
                success = True

        elif verb == "freeze" and count == 2:
            a = t[1]
            if a in bal and not frozen[a]:
                frozen[a] = True
                stack.append(("frz", a, False))
                success = True

        elif verb == "unfreeze" and count == 2:
            a = t[1]
            if a in bal and frozen[a]:
                frozen[a] = False
                stack.append(("frz", a, True))
                success = True

        if not success:
            rejected.append(i)

    return dict(bal), rejected
